/**
 * Generates typed ABIs (and, for the e2e test, bytecode) from Foundry's `contracts/out/`.
 * Never hand-type ABIs (code_standards.md). Run `forge build` in contracts/ first.
 *
 *   pnpm gen:abis           write the generated files
 *   pnpm gen:abis --check   exit 1 if they are out of date
 */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const OUT = fileURLToPath(new URL("../../contracts/out/", import.meta.url));
const KEEPER_FILE = fileURLToPath(new URL("../src/abis.generated.ts", import.meta.url));
const E2E_FILE = fileURLToPath(new URL("../test/e2e/artifacts.generated.ts", import.meta.url));

/** [export name, source file in out/, contract name] */
const KEEPER_ABIS = [
  ["rescueMarketAbi", "RescueMarket.sol", "RescueMarket"],
  ["vaultFactoryAbi", "VaultFactory.sol", "VaultFactory"],
  ["positionVaultAbi", "PositionVault.sol", "PositionVault"],
  ["hintHelpersAbi", "IHintHelpers.sol", "IHintHelpers"],
  ["sortedTrovesAbi", "ISortedTroves.sol", "ISortedTroves"],
] as const;

/** e2e: ABIs it needs beyond the keeper's, plus bytecode for contracts it deploys or etches. */
const E2E_ABIS = [
  ["borrowerOperationsAbi", "IBorrowerOperations.sol", "IBorrowerOperations"],
  ["troveManagerAbi", "ITroveManager.sol", "ITroveManager"],
  ["priceFeedAbi", "IPriceFeed.sol", "IPriceFeed"],
  ["erc20Abi", "IERC20.sol", "IERC20"],
  ["minimalFeePricerAbi", "MinimalFeePricer.sol", "MinimalFeePricer"],
  ["mockMezoOracleAbi", "MezoForkBase.sol", "MockMezoOracle"],
] as const;
const E2E_CREATION_CODE = [
  ["minimalFeePricerBytecode", "MinimalFeePricer.sol", "MinimalFeePricer"],
  ["vaultFactoryBytecode", "VaultFactory.sol", "VaultFactory"],
  ["rescueMarketBytecode", "RescueMarket.sol", "RescueMarket"],
] as const;
const E2E_RUNTIME_CODE = [["mockMezoOracleRuntime", "MezoForkBase.sol", "MockMezoOracle"]] as const;

interface Artifact {
  abi: unknown[];
  bytecode: { object: string };
  deployedBytecode: { object: string };
}

function artifact(file: string, name: string): Artifact {
  return JSON.parse(readFileSync(`${OUT}${file}/${name}.json`, "utf8")) as Artifact;
}

const HEADER = "// GENERATED by scripts/gen-abis.ts from contracts/out/. Do not edit; run `pnpm gen:abis`.\n";

export function generateKeeper(): string {
  const parts = KEEPER_ABIS.map(
    ([exportName, file, name]) =>
      `export const ${exportName} = ${JSON.stringify(artifact(file, name).abi, null, 2)} as const;\n`,
  );
  return HEADER + "\n" + parts.join("\n");
}

export function generateE2e(): string {
  const abis = E2E_ABIS.map(
    ([exportName, file, name]) =>
      `export const ${exportName} = ${JSON.stringify(artifact(file, name).abi, null, 2)} as const;\n`,
  );
  const creation = E2E_CREATION_CODE.map(
    ([exportName, file, name]) => `export const ${exportName} = "${artifact(file, name).bytecode.object}" as const;\n`,
  );
  const runtime = E2E_RUNTIME_CODE.map(
    ([exportName, file, name]) =>
      `export const ${exportName} = "${artifact(file, name).deployedBytecode.object}" as const;\n`,
  );
  return HEADER + "\n" + [...abis, ...creation, ...runtime].join("\n");
}

function main(): void {
  const targets: [string, string][] = [
    [KEEPER_FILE, generateKeeper()],
    [E2E_FILE, generateE2e()],
  ];
  if (process.argv.includes("--check")) {
    const stale = targets.filter(([path, content]) => readFileSync(path, "utf8") !== content).map(([p]) => p);
    if (stale.length > 0) {
      console.error(`Generated ABIs are stale: ${stale.join(", ")}. Run \`pnpm gen:abis\`.`);
      process.exit(1);
    }
    return;
  }
  for (const [path, content] of targets) writeFileSync(path, content);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
